import{_ as e,o as i,c as a,a8 as t}from"./chunks/framework.DpsX1MbM.js";const c=JSON.parse('{"title":"Prepare offline features with the capture plugin","description":"","frontmatter":{},"headers":[],"relativePath":"basic_usage/offline_capture.md","filePath":"sections/basic_usage/offline_capture.md","lastUpdated":1795414121000}'),n={name:"basic_usage/offline_capture.md"};function p(r,s,h,l,o,d){return i(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="prepare-offline-features-with-the-capture-plugin" tabindex="-1">Prepare offline features with the capture plugin <a class="header-anchor" href="#prepare-offline-features-with-the-capture-plugin" aria-label="Permalink to &quot;Prepare offline features with the capture plugin&quot;">​</a></h1><p>Offline preparation uses a CPU client, SGLang capture servers, and Mooncake:</p><p><code>dataset -&gt; plugin prefill -&gt; Mooncake -&gt; CPU client -&gt; .ckpt/.ckpt.gz</code></p><p>Offline colocated and disaggregated <strong>training</strong> continue to read these files; they do not need a capture server or a local ModelRunner. The preparation client does not import SGLang or load target model weights. It still needs the target&#39;s config/tokenizer and the same draft config used for training.</p><h2 id="start-the-services" tabindex="-1">Start the services <a class="header-anchor" href="#start-the-services" aria-label="Permalink to &quot;Start the services&quot;">​</a></h2><p>Use an SGLang environment with the native APIs described in the <a href="https://github.com/sgl-project/SpecForge/blob/main/plugins/sglang-spec-capture/README.md" target="_blank" rel="noreferrer">plugin installation guide</a>, and install the current plugin there. Use the SGLang commit pinned in <code>pyproject.toml</code>; released 0.5.23 still lacks the capture APIs. The server and SpecForge client may use the same environment with a compatible Mooncake wheel, or separate environments.</p><p>For a single-host TCP example, start a Mooncake master in a separate terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mooncake_master</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --enable-http-metadata-server=true</span></span></code></pre></div><p>Export the following in both the server and client terminals:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MOONCAKE_MASTER_SERVER_ADDR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">127.0.0.1:50051</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MOONCAKE_METADATA_SERVER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://127.0.0.1:8080/metadata</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MOONCAKE_LOCAL_HOSTNAME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">127.0.0.1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MOONCAKE_PROTOCOL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tcp</span></span></code></pre></div><p>Across hosts, replace loopback addresses with reachable addresses and set each process&#39;s <code>MOONCAKE_LOCAL_HOSTNAME</code> to its own reachable address. The offline CPU client supports TCP/RDMA; NVLink GPU receive buffers are not used here.</p><p>For <code>specforge/config/draft/presets/qwen3-8b-dflash.yaml</code>, launch this server in the SGLang environment:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SPECFORGE_SPEC_CAPTURE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SGLANG_SPEC_CAPTURE_GPU_PUT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">0</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">python </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sglang.launch_server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --model-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Qwen/Qwen3-8B</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skip-tokenizer-init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 30000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tp-size</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --speculative-algorithm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DFLASH</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --enable-return-aux-hidden-states</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --return-aux-hidden-state-layer-ids</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 17</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 25</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 33</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --return-hidden-states-mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> full</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --chunked-prefill-size</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -1</span></span></code></pre></div><p>Choose the method and layers from the resolved draft capture plan. Domino uses the DFLASH convention; EAGLE3 and DSpark use EAGLE3 and DSPARK respectively. The client checks every server&#39;s <code>/server_info</code> for the exact <code>model_path</code>, capture method, and ordered layer IDs. Use the same model identifier/path on both sides, and reinstall the plugin on existing servers to advertise these fields. TP size, device selection, attention backend, context length and radix cache options belong to the server command.</p><h2 id="capture-and-resume" tabindex="-1">Capture and resume <a class="header-anchor" href="#capture-and-resume" aria-label="Permalink to &quot;Capture and resume&quot;">​</a></h2><p>From the SpecForge environment:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/prepare_hidden_states.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --server-urls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:30000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --target-model-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Qwen/Qwen3-8B</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --draft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> specforge/config/draft/presets/qwen3-8b-dflash.yaml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --data-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./cache/dataset/sharegpt_train.jsonl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./cache/hidden_states/qwen3-8b-dflash-sharegpt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --chat-template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qwen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --max-length</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3072</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --batch-size</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32</span></span></code></pre></div><p>Add <code>--compress</code> for <code>.ckpt.gz</code>. The output retains the existing <code>rows_START-END/data_INDEX.ckpt[.gz]</code> layout and vocabulary mapping. Algorithms own the persisted feature names. Input IDs and loss masks remain client-side; the service only returns hidden-state artifacts.</p><p>Multiple <code>--server-urls</code> are used in round-robin order. To run concurrent CPU clients, replace <code>python</code> with <code>torchrun --standalone --nproc_per_node=4</code>. Workers partition samples without sampler padding or duplicate submissions; this worker count is independent of server TP size.</p><p>Rerun the same command to skip completed files. Changing the batch size or CPU worker count preserves sample IDs. Keep dataset contents/order, preprocessing, strategy, target, draft config, and file-group size unchanged when resuming; use a new output directory for a different dataset or capture configuration.</p><p>Writes use temporary files and atomic rename. The client waits for writes to finish before releasing temporary Mooncake objects, and attempts cleanup on request, read, or write errors. A response timeout fails the batch instead of silently retrying it. This is not a durable job/lease protocol: abrupt process termination or a server publication arriving after a timed-out request can leave objects until the store is reclaimed. Size the store for concurrent batches and use <code>--capture-timeout</code> appropriate to the target.</p><p>The service still runs SGLang&#39;s normal prefill/logits path with <code>max_new_tokens=0</code>; this migration does not bypass the target LM head.</p>`,22)])])}const g=e(n,[["render",p]]);export{c as __pageData,g as default};
